    """Generate file path for queue data"""
    return os.path.join(DATA_DIR, f"queue_{queue_name}.json")

def save_queue_data(queue_name, messages):
    """Save queue data to file"""
    queue_path = get_queue_path(queue_name)
    with open(queue_path, "w") as f:
        json.dump({
            "name": queue_name,
            "messages": messages
        }, f)

def load_queue_data(queue_name):
    """Load queue data from file"""
    queue_path = get_queue_path(queue_name)
    if os.path.exists(queue_path):
        with open(queue_path, "r") as f:
            return json.load(f)
    return None

# Route: POST /queues - Create new queue
