def create_queue():
    global queues_store

    data = request.get_json()

    if not data or "name" not in data:
        return jsonify({"error": "Invalid request body. Expected {'name': 'queue_name'}"}), 400

    queue_name = data["name"]

    # Validate queue name format
    if not queue_name or not isinstance(queue_name, str):
        return jsonify({"error": "Queue name must be a non-empty string"}), 400

    # Create new queue
    if queue_name not in queues_store:
        queues_store[queue_name] = {"messages": []}
        all_queues[queue_name] = {"status": "active", "created_at": datetime.now().isoformat()}

    # Save queue data to file
    save_queue_data(queue_name, queues_store[queue_name]["messages"])

    # Update status
    all_queues[queue_name] = {
        "status": "active",
        "created_at": all_queues.get(queue_name, {}).get("created_at"),
        "updated_at": datetime.now().isoformat()
    }

    return jsonify({
        "queue_name": queue_name,
        "status": "created",
        "message": "Queue created successfully"
    }), 201

# Route: POST /queues/{name}/messages - Send message
