def send_message(queue_name):
    global queues_store

    # Validate queue exists
    if queue_name not in queues_store:
        return jsonify({"error": f"Queue not found: {queue_name}"}), 404

    # Parse request body
    data = request.get_json()

    if not data or "content" not in data:
        return jsonify({"error": "Invalid request body. Expected {'content': 'message'}"}), 400

