    # Add message to queue (FIFO - append to end)
    queue_data["messages"].append({
        "content": message_content,
        "timestamp": datetime.now().isoformat()
    })

    # Update queue in storage
    queues_store[queue_name] = queue_data
    save_queue_data(queue_name, queue_data["messages"])

    # Update status
    all_queues[queue_name] = {
        "status": "active",
        "updated_at": datetime.now().isoformat()
    }

    return jsonify({
        "message_id": len(queue_data["messages"]) - 1,
        "content": message_content,
        "status": "sent"
    }), 201

# Route: GET /queues/{name}/messages - Consume message (FIFO)
@app.route(f"/queues/{queue_name}/messages", methods=["GET"])
def consume_message(queue_name):
