        "status": "active",
        "updated_at": datetime.now().isoformat()
    }

    # Save updated queue data
    save_queue_data(queue_name, queue_data["messages"])

    return jsonify({
        "message_id": message["message_id"],
        "content": message["content"],
        "timestamp": message["timestamp"]
    }), 200

